(sh, r) => { prev?.call(m, sh, r);
        if (k) {
          Object.assign(sh.uniforms, { uSD: { value: tex(k[0]) }, uSD2: { value: tex(k[3] || k[0]) }, uSM: { value: tex(k[4] || k[0]) }, uSS: { value: k[1] * s.scale }, uSH: { value: k[2] }, uSA: { value: s.amt } });
          sh.vertexShader = sh.vertexShader.replace('#include <common>', '#include <common>\nvarying vec3 vSW; varying vec3 vSN;')
            .replace('#include <begin_vertex>', `#include <begin_vertex>
              { vec4 sw = vec4(transformed, 1.); vec3 sn = objectNormal;
                #ifdef USE_INSTANCING
                  sw = instanceMatrix * sw; sn = mat3(instanceMatrix) * sn;
                #endif
                vSW = (modelMatrix * sw).xyz; vSN = normalize(mat3(modelMatrix) * sn); }`);
          sh.fragmentShader = sh.fragmentShader.replace('#include <common>', `#include <common>
              varying vec3 vSW; varying vec3 vSN; uniform sampler2D uSD, uSD2, uSM; uniform float uSS, uSH, uSA;
              float sH(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }
              float sN(vec2 p){ vec2 i = floor(p), f = fract(p); f = f * f * (3. - 2. * f); return mix(mix(sH(i), sH(i + vec2(1, 0)), f.x), mix(sH(i + vec2(0, 1)), sH(i + 1.), f.x), f.y); }
              vec3 sTri(sampler2D t, vec3 p, vec3 w){ return texture2D(t, p.zy).rgb * w.x + texture2D(t, p.xz).rgb * w.y + texture2D(t, p.xy).rgb * w.z; }`)
            .replace('#include <color_fragment>', `#include <color_fragment>
              { vec3 w = pow(abs(normalize(vSN)), vec3(4.)); w /= w.x + w.y + w.z; vec3 p = vSW * uSS;
                vec3 tx = sTri(uSD, p, w), av = texture2D(uSD, vec2(.5), 12.).rgb;
                ${k[4] ? 'float fd = smoothstep(18., 120., distance(vSW, cameraPosition)); tx = mix(tx, sTri(uSD, p * .21, w), fd);' : ''}
                ${k[3] ? `{ float bl = smoothstep(${k[4] ? ".3, .52" : ".38, .62"}, sN(vSW.xz * .03) * .7 + sN(vSW.xz * .11) * .3); tx = mix(tx, ${k[4] ? 'mix(sTri(uSD2, p * 1.3, w), sTri(uSD2, p * .27, w), fd)' : 'sTri(uSD2, p * 1.3, w)'}, bl); av = mix(av, texture2D(uSD2, vec2(.5), 12.).rgb, bl); }` : ''}
                float al = max(dot(av, vec3(.299, .587, .114)), .02);
                vec3 d = mix(vec3(dot(tx, vec3(.299, .587, .114))), tx, uSH) / al;     // detail around 1.0, so the material's own colour still sets the value
                ${k[4] ? '{ vec3 mr = texture2D(uSM, vSW.xz * .011).rgb / max(texture2D(uSM, vec2(.5), 12.).rgb, vec3(.02)); d *= mix(vec3(dot(mr, vec3(.299, .587, .114))), mr, .4); }' : ''}
                diffuseColor.rgb *= mix(vec3(1.), d, uSA); }`);
        }
        sh.fragmentShader = sh.fragmentShader.replace('#include <tonemapping_fragment>', `{ float rim = pow(1. - clamp(dot(normalize(normal), normalize(vViewPosition)), 0., 1.), 4.);
            rim *= 1. - smoothstep(.3, .7, (vec4(normalize(normal), 0.) * viewMatrix).y);
            gl_FragColor.rgb += vec3(.12, .17, .26) * rim * .18; }
          #include <tonemapping_fragment>`); }

